/**
 * Tests for the official Claude Code 2.1.296 secret-redaction alignment
 * (OCC-154 #016, changelog entry 16): "Fixed secret redaction in shared
 * transcripts and debug logs missing some values that follow a key with no
 * value, including in JSON written inside a shell string."
 *
 * Ground truth: every expected string below was machine-captured from a
 * scratch bundle assembled verbatim from the official 2.1.296 linux-x64 ELF
 * (md5 3c8749470f70a26efadf982b587e1548, secretRedaction module regions
 * @207282419 + jsonl chunk regions @215648000/@224385000) and executed under
 * Bun on a 29-input corpus (213 comparisons vs the 2.1.286 port; 27 diffs,
 * all v296 redacting strictly MORE). String literals are machine-generated
 * from that corpus run — none were retyped by hand.
 *
 * The regression block asserts the v286 behaviors that v296 provably keeps
 * byte-identical (corpus SAME rows), incl. the invisible-key fix (v286 #19).
 */
import { describe, expect, test } from 'bun:test'
import {
  redactJsonValue,
  redactKeyValue,
  redactSecrets,
  redactSecretsWithCap,
  redactTranscriptJsonl,
} from '../secretRedaction/index.js'


describe("2.1.296 #016: entry-16 escaped-JSON / key-with-no-value redaction (official v296 behavior)", () => {

  test("redacts the escaped-JSON value inside a single-quoted shell string (entry-16 core)", () => {
    // Arrange
    const input = "bash -c 'curl -d \"{\\\"api_key\\\": \\\"SECRETVALUE3\\\"}\" https://x'"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "bash -c 'curl -d \"{\\\"api_key\\\": \\\"SECRETVALUE3\\\"}\" https://x'"…)
    expect(actual).toBe("bash -c 'curl -d \"{\\\"api_key\\\": [REDACTED]\\\"}\" https://x'")
  })

  test("redacts a doubly-escaped JSON token value inside a shell string", () => {
    // Arrange
    const input = "sh -c \"echo \\\"{\\\\\\\"token\\\\\\\": \\\\\\\"SECRETVALUE4\\\\\\\"}\\\"\""

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "sh -c \"echo \\\"{\\\\\\\"token\\\\\\\": \\\\\\\"SECRETVALUE4\\\\\\\"}\\\"\""…)
    expect(actual).toBe("sh -c \"echo \\\"{\\\\\\\"token\\\\\\\": [REDACTED]\\\\\\\"}\\\"\"")
  })

  test("redacts escaped client_secret JSON inside python -c", () => {
    // Arrange
    const input = "python -c \"print('{\\\"client_secret\\\": \\\"SECRETVALUE11\\\"}')\""

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "python -c \"print('{\\\"client_secret\\\": \\\"SECRETVALUE11\\\"}')\""…)
    expect(actual).toBe("python -c \"print('{\\\"client_secret\\\": [REDACTED]\\\"}')\"")
  })

  test("redacts escaped api_key JSON inside git commit -m", () => {
    // Arrange
    const input = "git commit -m \"{\\\"api_key\\\": \\\"SECRETVALUE12\\\"}\""

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "git commit -m \"{\\\"api_key\\\": \\\"SECRETVALUE12\\\"}\""…)
    expect(actual).toBe("git commit -m \"{\\\"api_key\\\": [REDACTED]\\\"}\"")
  })

  test("redactKeyValue redacts the escaped-JSON tail (fallback chain)", () => {
    // Arrange
    const input = "bash -c 'curl -d \"{\\\"api_key\\\": \\\"SECRETVALUE3\\\"}\" https://x'"

    // Act
    const actual = redactKeyValue('api_key', input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED] -c 'curl -d \"{\\\"api_key\\\": \\\"SECRETVALUE3\\\"}\" https://x'"…)
    expect(actual).toBe("[REDACTED] -c 'curl -d \"{\\\"api_key\\\": [REDACTED]\\\"}\" https://x'")
  })

  test("redactJsonValue propagates the escaped-JSON fix to object values", () => {
    // Arrange
    const input = "bash -c 'curl -d \"{\\\"api_key\\\": \\\"SECRETVALUE3\\\"}\" https://x'"

    // Act
    const actual = redactJsonValue({ k: input })

    // Assert (v296 ground truth; v286 produced: "{\"k\":\"bash -c 'curl -d \\\"{\\\\\\\"api_key\\\\\\\": \\\\\\\"SECRETVALUE3\\\\\\\"}\\\" https://x'\"}"…)  [GT stored JSON.stringify-ed: b9 returns a null-prototype object for object input, same as v286 M4]
    expect(JSON.stringify(actual)).toBe("{\"k\":\"bash -c 'curl -d \\\"{\\\\\\\"api_key\\\\\\\": [REDACTED]\\\\\\\"}\\\" https://x'\"}")
  })

  test("redactSecretsWithCap propagates the escaped-JSON fix", () => {
    // Arrange
    const input = "bash -c 'curl -d \"{\\\"api_key\\\": \\\"SECRETVALUE3\\\"}\" https://x'"

    // Act
    const actual = redactSecretsWithCap(input, 4096)

    // Assert (v296 ground truth; v286 produced: "bash -c 'curl -d \"{\\\"api_key\\\": \\\"SECRETVALUE3\\\"}\" https://x'"…)
    expect(actual).toBe("bash -c 'curl -d \"{\\\"api_key\\\": [REDACTED]\\\"}\" https://x'")
  })

  test("redactKeyValue: value following a key with no value is redacted", () => {
    // Arrange
    const input = "api_key= token=SECRETVALUE5"

    // Act
    const actual = redactKeyValue('api_key', input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED] token=[REDACTED]"…)
    expect(actual).toBe("[REDACTED] [REDACTED]")
  })

  test("redactKeyValue: colon-form 'password: SECRET' value no longer leaks", () => {
    // Arrange
    const input = "password: SECRETVALUE8"

    // Act
    const actual = redactKeyValue('api_key', input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED] SECRETVALUE8"…)
    expect(actual).toBe("[REDACTED] [REDACTED]")
  })

  test("redactKeyValue: second assignment after an empty key is redacted", () => {
    // Arrange
    const input = "AWS_ACCESS_KEY= AWS_SECRET_KEY=SECRETVALUE10"

    // Act
    const actual = redactKeyValue('api_key', input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED] AWS_SECRET_KEY=[REDACTED]"…)
    expect(actual).toBe("[REDACTED] [REDACTED]")
  })

  test("redactKeyValue redacts a plain JSON object value", () => {
    // Arrange
    const input = "{\"api_key\": \"SECRETVALUE2\"}"

    // Act
    const actual = redactKeyValue('api_key', input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED] \"SECRETVALUE2\"}"…)
    expect(actual).toBe("[REDACTED] \"[REDACTED]\"}")
  })

  test("redactKeyValue redacts a quoted sk-proj value", () => {
    // Arrange
    const input = "openai_api_key = \"sk-proj-0123456789abcdefghijklmnopqrstuvwx\""

    // Act
    const actual = redactKeyValue('api_key', input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED] = \"sk-proj-0123456789abcdefghijklmnopqrstuvwx\""…)
    expect(actual).toBe("[REDACTED] = \"[REDACTED]\"")
  })

  test("redactKeyValue redacts a Bearer value (key-with-no-value shape)", () => {
    // Arrange
    const input = "Authorization: Bearer SECRETVALUE16"

    // Act
    const actual = redactKeyValue('api_key', input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED] Bearer SECRETVALUE16"…)
    expect(actual).toBe("[REDACTED] [REDACTED]")
  })

  test("transcript JSONL: escaped JSON inside a message string is redacted, output stays valid JSON", () => {
    // Arrange
    const input = "{\"type\":\"user\",\"message\":{\"content\":\"run bash -c '{\\\\\\\"api_key\\\\\\\": \\\\\\\"SECRETVALUE17\\\\\\\"}'\"}}\n{\"type\":\"api-request-2\",\"requestId\":\"ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12\",\"key\":\"sk-ant-api03-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\"}\nnotjson api_key=SECRETVALUE18\n"

    // Act
    const actual = redactTranscriptJsonl(input)

    // Assert (v296 ground truth; v286 produced: "{\"type\":\"user\",\"message\":{\"content\":\"run bash -c '{\\\\\\\"api_key\\\\\\\": \\\\\\\"SECRETVALUE17\\\\\\\"}'\"}…)
    expect(actual).toBe("{\"type\":\"user\",\"message\":{\"content\":\"run bash -c '{\\\\\\\"api_key\\\\\\\": [REDACTED]\\\\\\\"}'\"}}\n{\"type\":\"line-withheld\",\"bytes\":29}\n")
  })

  test("whole-transcript text redaction catches the escaped JSON value", () => {
    // Arrange
    const input = "{\"type\":\"user\",\"message\":{\"content\":\"run bash -c '{\\\\\\\"api_key\\\\\\\": \\\\\\\"SECRETVALUE17\\\\\\\"}'\"}}\n{\"type\":\"api-request-2\",\"requestId\":\"ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12\",\"key\":\"sk-ant-api03-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\"}\nnotjson api_key=SECRETVALUE18\n"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "{\"type\":\"user\",\"message\":{\"content\":\"run bash -c '{\\\\\\\"api_key\\\\\\\": \\\\\\\"SECRETVALUE17\\\\\\\"}'\"}…)
    expect(actual).toBe("{\"type\":\"user\",\"message\":{\"content\":\"run bash -c '{\\\\\\\"api_key\\\\\\\": [REDACTED]\\\\\\\"}'\"}}\n{\"type\":\"api-request-2\",\"requestId\":\"ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12ab12\",\"key\":\"[REDACTED]\"}\nnotjson api_key=[REDACTED]\n")
  })

})

describe("2.1.296 #016: v286 behaviors preserved byte-identically in v296 (corpus SAME rows)", () => {

  test("invisible-character key name still redacted (v286 bullet #19 preserved)", () => {
    // Arrange
    const input = "to​ken=SECRETVALUE15"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "to​ken=[REDACTED]"…)
    expect(actual).toBe("to​ken=[REDACTED]")
  })

  test("PEM private-key block still redacted", () => {
    // Arrange
    const input = "-----BEGIN PRIVATE KEY-----\nMIIBSECRET\n-----END PRIVATE KEY-----"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "-----BEGIN PRIVATE KEY-----\nMIIBSECRET\n-----END PRIVATE KEY-----"…)
    expect(actual).toBe("-----BEGIN PRIVATE KEY-----\nMIIBSECRET\n-----END PRIVATE KEY-----")
  })

  test("loose JWT still redacted", () => {
    // Arrange
    const input = "eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxMjM0NTY3ODkwIn0.dozjgNryP4J3jVmNHl0w5N_XgL0n3I9PlFUP0THsR8U"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "[REDACTED]"…)
    expect(actual).toBe("[REDACTED]")
  })

  test("anthropic api key assignment still redacted", () => {
    // Arrange
    const input = "ANTHROPIC_API_KEY=sk-ant-api03-0123456789abcdefghijklmnopqrstuvwxyzABC"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "ANTHROPIC_API_KEY=[REDACTED]"…)
    expect(actual).toBe("ANTHROPIC_API_KEY=[REDACTED]")
  })

  test("aws secret access key still redacted", () => {
    // Arrange
    const input = "aws_secret_access_key=wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "aws_secret_access_key=[REDACTED]"…)
    expect(actual).toBe("aws_secret_access_key=[REDACTED]")
  })

  test("long input past the 512-cursor: trailing secret still redacted", () => {
    // Arrange
    const input = "api_ secret=SECRETVALUE14"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "api_key=[REDACTED] secret=[REDACTED]"…)
    expect(actual).toBe("api_key=[REDACTED] secret=[REDACTED]")
  })

  test("unescaped key-with-no-value JSON redacted identically in v286/v296", () => {
    // Arrange
    const input = "{\"api_key\": , \"token\": \"SECRETVALUE6\"}"

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "{\"api_key\": , \"token\": \"[REDACTED]\"}"…)
    expect(actual).toBe("{\"api_key\": , \"token\": \"[REDACTED]\"}")
  })

  test("mixed empty/non-empty echo assignments behave identically", () => {
    // Arrange
    const input = "echo \"token=\" ; echo \"token=SECRETVALUE13\""

    // Act
    const actual = redactSecrets(input)

    // Assert (v296 ground truth; v286 produced: "echo \"token=\"[REDACTED]\"token=[REDACTED]"…)
    expect(actual).toBe("echo \"token=\"[REDACTED]\"token=[REDACTED]")
  })

  test("30k-char capped redaction unchanged", () => {
    // Arrange
    const input = " api_key=SECRETVALUE19"

    // Act
    const actual = redactSecretsWithCap(input, 4096)

    // Assert (v296 ground truth; v286 produced: "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx…)
    expect(actual).toBe(" api_key=[REDACTED]")
  })

})
